export type DictionaryCategory =
  | 'Philosophy'
  | 'Yoga'
  | 'Deity'
  | 'Scripture'
  | 'Soul & Liberation'
  | 'Cosmology'
  | 'Practice';

export interface DictionaryTerm {
  id: number;
  tamil: string;
  transliteration: string;
  english: string;
  explanation: string;
  category: DictionaryCategory;
  // verse IDs (id = verseNumber + 1) that directly illustrate this term
  verseRefs?: number[];
}

export const CATEGORY_COLORS: Record<DictionaryCategory, string> = {
  'Philosophy':       '#C8860A',
  'Yoga':             '#7B4EA0',
  'Deity':            '#C0392B',
  'Scripture':        '#1A6B8A',
  'Soul & Liberation':'#2E7D32',
  'Cosmology':        '#BF360C',
  'Practice':         '#006064',
};

// Sorted A–Z by transliteration
export const DICTIONARY_TERMS: DictionaryTerm[] = [
  { id: 1,   tamil: "அகம்",              transliteration: "agam",           english: "Inner / Within",                    explanation: "The interior space of the heart and consciousness. In the Thirumanthiram, Shiva is repeatedly said to dwell 'within' (agam), making the inner world the primary locus of spiritual discovery rather than any external place or ritual.", category: "Philosophy", verseRefs: [276, 82] },
  { id: 2,   tamil: "ஆகமம்",            transliteration: "āgamam",          english: "Agama Scripture",                   explanation: "The authoritative scriptural corpus of Shaivism, revealed by Shiva and transmitted through the guru lineage. The Agamas specify temple worship, yoga, philosophy, and ritual in precise detail. Thirumoolar's Thirumanthiram is one of the few Tamil works that directly transmits Agamic knowledge.", category: "Scripture", verseRefs: [2, 885] },
  { id: 3,   tamil: "அகந்தை",           transliteration: "aganthai",         english: "Ego / I-sense",                     explanation: "The false identification of the self with body and mind rather than with pure consciousness. The ego (ahamkāra in Sanskrit) is the root cause of bondage. Yoga and grace together dissolve this illusory sense of a separate self.", category: "Philosophy" },
  { id: 4,   tamil: "ஆகாயம்",           transliteration: "ākāyam",           english: "Ether / Space",                     explanation: "The first and subtlest of the five elements (pañca bhūta). Ākāśa corresponds to the throat centre and to the principle of sound. In the Thirumanthiram, the boundless inner space of pure consciousness is repeatedly compared to the open sky.", category: "Cosmology" },
  { id: 5,   tamil: "ஆண்டவன்",          transliteration: "āṇḍavaṉ",          english: "Lord / Ruler",                      explanation: "A common name for Shiva meaning 'the Lord who rules.' Āṇḍavan governs all of creation from within — not as an external tyrant but as the very intelligence that organises every atom and every soul.", category: "Deity" },
  { id: 6,   tamil: "ஆணவம்",            transliteration: "āṇavam",           english: "Primordial Egoism",                 explanation: "The first and most fundamental of the three bonds (pāśa) that bind the soul. Āṇava is the original contraction of consciousness — the feeling of being small and separate — from which all suffering and karma arise. Only Shiva's grace can fully dissolve it.", category: "Soul & Liberation" },
  { id: 7,   tamil: "அண்டம்",           transliteration: "aṇḍam",            english: "Cosmos / Universe",                 explanation: "The macrocosm — the external universe in all its vastness. Thirumoolar establishes that what exists in the cosmos (aṇḍam) also exists in the human body (piṇḍam), making the body a complete map of the cosmos and yoga a direct science of cosmic knowledge.", category: "Cosmology" },
  { id: 8,   tamil: "அன்பு",            transliteration: "anbu",             english: "Love / Devotion",                   explanation: "The most fundamental quality of the liberated soul and the very nature of Shiva. In Thirumoolar's radical formulation — Anbe Sivam — love is not merely a path toward Shiva but is Shiva Himself. All practices in the Thirumanthiram ultimately serve to uncover this love.", category: "Philosophy", verseRefs: [276, 82] },
  { id: 9,   tamil: "அன்பே சிவம்",      transliteration: "anbe sivam",        english: "Love is Shiva",                     explanation: "The single most celebrated declaration in the entire Thirumanthiram (verse 81). This four-word phrase is both a complete philosophy and a direct experiential pointer: the experience of unconditional love and the experience of Shiva are not two different things.", category: "Philosophy", verseRefs: [82, 276] },
  { id: 10,  tamil: "அருள்",            transliteration: "aruḷ",             english: "Grace / Divine Grace",              explanation: "Shiva's unconditional compassion that actively works to bring all souls toward liberation. Unlike karma which is earned through action, aruḷ is freely given. The entire Thirumanthiram can be read as a detailed account of how divine grace operates and how the soul can open itself to receive it.", category: "Deity", verseRefs: [2, 3] },
  { id: 11,  tamil: "அருட்பெரும் சோதி", transliteration: "aruṭperum jōthi",  english: "Great Light of Grace",              explanation: "One of the most exalted names of Shiva in Tamil tradition — 'the vast, radiant light of divine grace.' This is also the title of the great mystical poem by the 19th-century saint Vallalar, who identified this inner light as the supreme form of the divine.", category: "Deity", verseRefs: [2] },
  { id: 12,  tamil: "ஆத்மா",            transliteration: "āttmā",            english: "Soul / Self",                       explanation: "The individual soul — one of the three eternal realities in Shaiva Siddhanta. The soul exists eternally but is currently bound by the three pāśas. Through grace and yoga, it is progressively liberated until it exists in eternal conscious union with Shiva.", category: "Soul & Liberation", verseRefs: [2123, 2650] },
  { id: 13,  tamil: "ஆவி",              transliteration: "āvi",              english: "Breath / Spirit / Life-force",       explanation: "Refers to both the physical breath and the prāṇa (life-force) that animates the body. In the Thirumanthiram, the breath is the most direct connection between the individual and the cosmos — controlling the breath is the master key to controlling the mind.", category: "Yoga", verseRefs: [550] },
  { id: 14,  tamil: "அஷ்டாங்க யோகம்",  transliteration: "aṣṭāṅga yōgam",    english: "Eightfold Yoga",                    explanation: "The classical eight-limbed yoga system: Yama, Niyama, Āsana, Prāṇāyāma, Pratyāhāra, Dhāraṇā, Dhyāna, and Samādhi. The entirety of Tantra 3 of the Thirumanthiram expounds this system in comprehensive detail, making it one of the oldest Tamil yogic manuals.", category: "Yoga", verseRefs: [550, 551] },
  { id: 15,  tamil: "பந்தம்",           transliteration: "bantham",          english: "Bond / Bondage",                    explanation: "The condition of the soul bound to the cycle of birth and death. Shaiva Siddhanta identifies three bonds: āṇava (primordial ego), karma, and māyā. Liberation is the complete dissolution of all three bonds through Shiva's grace, not through the soul's own unaided effort.", category: "Soul & Liberation", verseRefs: [2123, 2650] },
  { id: 16,  tamil: "சக்தி",            transliteration: "cakti",            english: "Divine Energy / Power of Shiva",    explanation: "The dynamic, creative energy of Shiva — both the power of Shiva and the Goddess Herself as a distinct reality. Shakti is not separate from Shiva but is His own power of expression. Tantra 4 of the Thirumanthiram dedicates many verses to the glory of Shakti in all her forms.", category: "Deity", verseRefs: [885, 2] },
  { id: 17,  tamil: "சமாதி",            transliteration: "camādhi",          english: "Complete Absorption / Union",        explanation: "The eighth limb of Ashtanga yoga — the state of complete absorption of the individual mind into pure consciousness. In Shaiva yoga, samādhi is not an achievement but a revelation: the direct recognition that the individual and Shiva were never actually separate.", category: "Yoga", verseRefs: [550, 2123] },
  { id: 18,  tamil: "சரண்",             transliteration: "caraṇ",            english: "Refuge / Surrender",                explanation: "Taking refuge at the feet of Shiva or the guru. Surrender is not passive submission but an active reorientation of the will — instead of the ego directing life, the soul consciously aligns itself with Shiva's intelligence. This is the beginning of liberation.", category: "Practice", verseRefs: [2, 35] },
  { id: 19,  tamil: "சித்தம்",          transliteration: "cittam",           english: "Mind-stuff / Consciousness-field",   explanation: "The total mental apparatus — memory, ego, intellect, and raw awareness combined. In yoga, purifying the citta is the central project: removing the obscurations that prevent the citta from reflecting pure consciousness clearly, like polishing a mirror.", category: "Philosophy", verseRefs: [550] },
  { id: 20,  tamil: "சித்தர்",          transliteration: "cittar",           english: "Siddhar / Perfected One",            explanation: "A perfected yogi who has attained both liberation and supernatural powers through intensive practice. The Tamil Siddhar tradition, of which Thirumoolar is the most prominent voice, emphasises the complete transformation of body and mind into vehicles of divine consciousness.", category: "Soul & Liberation", verseRefs: [80, 1705] },
  { id: 21,  tamil: "சித்தி",           transliteration: "citti",            english: "Supernatural Power / Attainment",    explanation: "The eight great supernatural powers attained by advanced yogis: miniaturisation, magnification, levitation, extension, omnipresence, mastery, lordship, and creative power. Tantra 7 of the Thirumanthiram expounds these in detail, while warning that siddhis are not the goal but by-products of genuine liberation.", category: "Yoga", verseRefs: [1705, 1706] },
  { id: 22,  tamil: "சிவம்",            transliteration: "civam",            english: "Shiva / Absolute Goodness",          explanation: "The supreme reality of Shaivism — both the personal God and the impersonal absolute. The word means 'the auspicious one' or 'absolute goodness.' Thirumoolar uses Sivam to mean both the transcendent absolute and the loving, intimate divine presence accessible in the heart.", category: "Deity", verseRefs: [2, 82, 276] },
  { id: 23,  tamil: "சோதி",             transliteration: "cōti",             english: "Light / Divine Flame",               explanation: "A key image in the Thirumanthiram for Shiva's nature — pure luminous awareness that illumines everything without itself being illumined by anything external. Thirumoolar frequently describes the inner experience of Shiva as a blazing, self-luminous light at the crown of the head.", category: "Deity", verseRefs: [2, 2123] },
  { id: 24,  tamil: "சுழுமுனை",         transliteration: "cuḻumuṉai",        english: "Sushumna / Central Channel",         explanation: "The central energy channel (nāḍī) running along the spine through which the Kundalini energy rises during advanced yoga. In the Thirumanthiram, awakening the sushumna by balancing the solar and lunar channels is the core technical teaching of the yogic path.", category: "Yoga", verseRefs: [550, 885] },
  { id: 25,  tamil: "தத்துவம்",         transliteration: "tattuam",          english: "Principle / Category of Reality",    explanation: "The fundamental principles or categories that constitute reality. Shaiva Siddhanta enumerates 36 tattvas from pure Shiva-consciousness at the summit to earth at the base. Knowing the tattvas is the cosmological framework of Shaiva thought.", category: "Philosophy", verseRefs: [338, 2123] },
  { id: 26,  tamil: "தந்திரம்",         transliteration: "tanttiram",        english: "Tantra / Sacred Method / Section",   explanation: "Both a title for each of the nine sections of the Thirumanthiram and a term for the broader tradition of Tantric practice. Tantra means 'that which expands' — practices that expand consciousness by working through the body and senses rather than against them.", category: "Scripture", verseRefs: [2, 338] },
  { id: 27,  tamil: "தீட்சை",           transliteration: "thīṭcai",          english: "Initiation / Dīkṣā",                explanation: "The formal transmission of spiritual power from guru to disciple that begins the disciple's journey in earnest. In Shaiva tradition, dīkṣā is not merely a ceremony but an actual transmission of grace that begins the real dissolution of the soul's three bonds.", category: "Practice", verseRefs: [1574] },
  { id: 28,  tamil: "திருவருள்",        transliteration: "thiruvaruḷ",       english: "Sacred Divine Grace",               explanation: "The most exalted expression for Shiva's grace in Tamil tradition — combining thiru (sacred, auspicious) with aruḷ (grace). Thiruvaruḷ is not passive kindness but the active, intelligent divine power that specifically works to dissolve the soul's bonds and bring it to liberation.", category: "Deity", verseRefs: [2, 3] },
  { id: 29,  tamil: "திருமூலர்",        transliteration: "thirumūlar",       english: "Thirumoolar / Sacred Mulan",         explanation: "The author of the Thirumanthiram — a Siddhar yogi from Kailash who came to Tamil Nadu, inhabited the body of a cowherd named Mulan, and over thousands of years composed 3,047 verses of direct spiritual transmission from samādhi.", category: "Deity", verseRefs: [80, 82, 69] },
  { id: 30,  tamil: "தொண்டு",           transliteration: "thoṇḍu",           english: "Service / Devoted Service",          explanation: "Selfless service rendered to Shiva and to all beings as a natural expression of love. In Shaiva devotion, thoṇḍu is not servile duty but love made active — the overflow of devotion expressed as care, dedication, and tireless service to others.", category: "Practice" },
  { id: 31,  tamil: "ஈசன்",             transliteration: "īcan",             english: "The Ruler / Lord Shiva",             explanation: "A common name for Shiva meaning 'the Lord' or 'the Ruler.' In the Thirumanthiram, Īśan is both the cosmic sovereign who governs all reality through His five acts, and the intimate, accessible presence dwelling in the heart of every being without distinction.", category: "Deity", verseRefs: [2, 338] },
  { id: 32,  tamil: "இச்சை",            transliteration: "icai",             english: "Will / Desire-power",               explanation: "The power of divine will — one of the five shaktis of Shiva. In the purified soul, icchā-śakti becomes aligned with Shiva's will, at which point there is no longer any meaningful distinction between personal desire and the purpose of the divine. Yoga purifies this faculty.", category: "Philosophy" },
  { id: 33,  tamil: "இடகலை",            transliteration: "iḍakalai",         english: "Ida / Left Lunar Channel",           explanation: "The left energy channel (nāḍī) in yogic physiology, associated with the moon, cooling energy, the feminine principle, and the in-breath. When the solar (piṅgalā) and lunar (iḍā) channels are balanced, the central channel (suṣumnā) opens spontaneously.", category: "Yoga", verseRefs: [550, 885] },
  { id: 34,  tamil: "கண்ணி மணி",       transliteration: "kaṇṇin maṇi",      english: "Jewel of the Eye",                  explanation: "A poetic image in the Thirumanthiram for the subtle centre of inner vision — the spiritual faculty of direct perception through which Shiva is perceived. When attention rests at this inner centre, the divine light becomes visible to the purified awareness.", category: "Practice" },
  { id: 35,  tamil: "கர்மம்",           transliteration: "karmam",           english: "Karma / Action-residue",             explanation: "The accumulated residue of past actions that shapes present experience and binds the soul to rebirth. Karma is the second of the three bonds (pāśa). It is not punishment but a natural law — actions create tendencies that continue until dissolved by grace and awareness.", category: "Soul & Liberation", verseRefs: [2, 114] },
  { id: 36,  tamil: "கிரியை",           transliteration: "kiriyai",          english: "Action / Ritual Action (Kriyā)",     explanation: "The path of ritual action and worship as a means of spiritual progress. Kriyā is one of the four approaches (pādas) of the Shaiva Agamas, along with Caryā (ethics), Yoga (inner practice), and Jñāna (knowledge). All four are necessary for complete realisation.", category: "Practice" },
  { id: 37,  tamil: "குரு",             transliteration: "guru",             english: "Spiritual Teacher",                  explanation: "The spiritual master who transmits knowledge and grace to the disciple. In Shaiva tradition, the guru is not merely a human teacher but a manifestation of Shiva's grace — Shiva Himself appearing in human form to guide the soul. Nandi is considered the primordial guru of all.", category: "Practice", verseRefs: [1574, 69, 2] },
  { id: 38,  tamil: "லட்சணம்",          transliteration: "laṭcaṇam",         english: "Sign / Characteristic / Lakshana",  explanation: "The signs or characteristics by which a realised master can be recognised — absence of fear, absence of pride, constant equanimity, all-pervading compassion. Thirumoolar lists several lakshanas of the liberated one to guide disciples in recognising genuine spiritual attainment.", category: "Soul & Liberation" },
  { id: 39,  tamil: "லிங்கம்",          transliteration: "liṅgam",           english: "Shiva's Form / Axis of Consciousness", explanation: "The primary iconic form of Shiva worship — an upright column representing the infinite, self-luminous axis of consciousness. In Thirumoolar's teaching, the liṅgam is both an external object of worship and an inner reality — the pillar of pure awareness at the centre of the body.", category: "Deity", verseRefs: [1705, 885] },
  { id: 40,  tamil: "மந்திரம்",         transliteration: "manthiram",        english: "Sacred Formula / Mantra",            explanation: "A sacred syllable or phrase whose sustained repetition purifies the mind and reveals the divine. The Thirumanthiram itself — Thiru-manthiram — means 'the sacred mantra,' implying the entire text is itself a mantra that liberates those who receive it with devotion.", category: "Practice", verseRefs: [885, 886] },
  { id: 41,  tamil: "மனம்",             transliteration: "manam",            english: "Mind",                              explanation: "The instrument of knowing, feeling, and willing that mediates between consciousness and the world. The Thirumanthiram identifies the mind as the single most important factor in bondage and liberation — the same mind that creates suffering, when purified, becomes the very dwelling place of Shiva.", category: "Philosophy", verseRefs: [550, 276] },
  { id: 42,  tamil: "மாயை",             transliteration: "māyai",            english: "Illusion / Matter-energy",           explanation: "The third of the three bonds (pāśa) — the cosmic principle of material existence and apparent multiplicity that causes the soul to identify with the body rather than with consciousness. In Shaiva Siddhanta, māyā is real but subservient to Shiva's will.", category: "Soul & Liberation", verseRefs: [2123, 338] },
  { id: 43,  tamil: "முக்தி",           transliteration: "mukti",            english: "Liberation / Freedom",              explanation: "The complete freedom of the soul from all bonds — the goal of all spiritual life. In Shaiva Siddhanta, mukti is not annihilation of the individual but its fulfillment: the soul, freed from the three bonds, exists in eternal loving conscious union with Shiva.", category: "Soul & Liberation", verseRefs: [2650, 2651, 2123] },
  { id: 44,  tamil: "மூலம்",            transliteration: "mūlam",            english: "Root / Origin",                     explanation: "The root or ultimate source. In yogic physiology, the mūlādhāra chakra at the base of the spine is the seat of dormant Kundalini energy. In philosophy, Shiva as mūlam is the uncaused cause — the root from which all existence springs without any prior cause.", category: "Yoga", verseRefs: [550, 2] },
  { id: 45,  tamil: "நந்தி",            transliteration: "nanti",            english: "Nandi / Divine Bull / Primordial Guru", explanation: "Shiva's sacred vehicle and the first teacher of the Shaiva yoga lineage. Thirumoolar received initiation directly from Nandi at Kailash, making Nandi his root guru. Nandi represents the pure, faithful soul that carries the divine and dwells always in Shiva's presence.", category: "Deity", verseRefs: [2, 3, 69] },
  { id: 46,  tamil: "நமசிவாய",          transliteration: "namasivāya",       english: "Na-Ma-Si-Va-Ya (Panchakshara)",      explanation: "The five-syllable sacred mantra of Shaivism. Na = earth/Brahma, Ma = water/Vishnu, Si = fire/Rudra, Va = air/Maheshvara, Ya = space/Sadāshiva. These five syllables contain the entire cosmology of Shaivism and the complete path of liberation within them.", category: "Practice", verseRefs: [885, 886, 887] },
  { id: 47,  tamil: "நிலை",             transliteration: "nilai",            english: "State / Ground / Stability",         explanation: "The stable ground of being — the unwavering state of the liberated yogi who is no longer moved by the fluctuations of mind and circumstance. 'Established in silence' (mōṉē nilaiperṟār) is Thirumoolar's description of the ones who have found this unshakeable ground in Shiva.", category: "Soul & Liberation", verseRefs: [2650, 2123] },
  { id: 48,  tamil: "ஓம்",              transliteration: "ōm",               english: "Om / Pranava",                      explanation: "The primordial sacred syllable composed of A, U, and M, representing the three states of consciousness and transcending them into the fourth (turiya). Om is the sound-form of Shiva and the seed of all mantras. Meditation on Om is described as equivalent to meditating on Shiva directly.", category: "Practice", verseRefs: [885, 2] },
  { id: 49,  tamil: "ஒளி",              transliteration: "oḷi",              english: "Light / Luminosity",                explanation: "A primary metaphor in the Thirumanthiram for Shiva's nature and for the inner experience of the divine. Thirumoolar uses light imagery constantly — inner light, light of grace, light at the crown — pointing to the self-luminous nature of pure consciousness that illumines everything without itself needing illumination.", category: "Deity", verseRefs: [2, 2123] },
  { id: 50,  tamil: "பாடல்",            transliteration: "pāḍal",            english: "Song / Verse",                      explanation: "Each of the 3,047 verses of the Thirumanthiram. Unlike literary compositions, Thirumoolar's pāḍal are described as direct transmissions from deep samādhi — each verse a report of lived spiritual experience, composed once each year after emerging from prolonged absorption.", category: "Scripture", verseRefs: [82, 2] },
  { id: 51,  tamil: "பரகாயப் பிரவேசம்", transliteration: "parakāya pravēsam", english: "Entry into Another Body",           explanation: "The yogic power by which a yogi can vacate their own body and inhabit another. This is the central miracle in Thirumoolar's biography — he entered the body of the dead cowherd Mulan. This led directly to his remaining in Tamil Nadu and composing the Thirumanthiram.", category: "Yoga", verseRefs: [80] },
  { id: 52,  tamil: "பரம்",             transliteration: "param",            english: "The Supreme / Transcendent",         explanation: "The highest or transcendent aspect of Shiva — beyond all qualities, forms, and concepts. Shiva is both param (transcendent) and aparam (immanent). To realise Shiva as param is the pinnacle of the highest knowledge (parā jñāna) described in the Thirumanthiram.", category: "Deity", verseRefs: [2, 2123] },
  { id: 53,  tamil: "பசு",              transliteration: "pacu",             english: "Soul / Bound Being",                 explanation: "Literally 'cow,' used in Shaiva Siddhanta as a technical term for the individual soul in its bound state. The term emphasises the soul's current dependence and ignorance — like a domestic animal tethered to a post — without implying this is its permanent or essential nature.", category: "Soul & Liberation", verseRefs: [2123, 114] },
  { id: 54,  tamil: "பாசம்",            transliteration: "pācam",            english: "Bond / Fetter / Noose",              explanation: "Literally 'rope' or 'noose,' the technical Shaiva term for the three bonds that bind the soul: āṇava, karma, and māyā. The pāśa is real but not eternal — it can be dissolved by Shiva's grace. All of spiritual life is, in essence, the process of untying these three knots.", category: "Soul & Liberation", verseRefs: [2123, 338] },
  { id: 55,  tamil: "பதி",              transliteration: "pathi",            english: "Lord / God (Shiva) — First Eternal", explanation: "The first of the three eternal realities in Shaiva Siddhanta: Pati (God), Paśu (soul), Pāśa (bond). Pati means 'Lord' or 'master' — the supreme reality that is eternally free, omniscient, and omnipotent. Shiva as Pati is the ultimate refuge and the final truth.", category: "Deity", verseRefs: [2, 2123] },
  { id: 56,  tamil: "பிண்டம்",          transliteration: "piṇḍam",           english: "Body / Microcosm",                   explanation: "The individual human body, understood as a microcosm of the entire universe (aṇḍam). What exists in the cosmos exists in the body — this equivalence is the foundation of the entire yogic science of the Thirumanthiram and justifies the body as the primary field of spiritual investigation.", category: "Cosmology", verseRefs: [2, 550] },
  { id: 57,  tamil: "பிராணன்",          transliteration: "prāṇan",           english: "Life-force / Prana",                explanation: "The vital energy that animates the body and connects individual consciousness to the cosmic. Through prāṇāyāma (breath control), the yogi can influence the flow of prāṇa through all channels, purifying the subtle body and quieting the mind for deep meditation.", category: "Yoga", verseRefs: [550, 551] },
  { id: 58,  tamil: "புலன்கள்",         transliteration: "pulankaḷ",         english: "Senses / Sense Faculties",           explanation: "The five senses — sight, sound, smell, taste, touch — and their corresponding organs. In yoga, the senses are instruments of knowledge that must be trained to turn inward (pratyāhāra). When properly directed, they become transparent windows to the divine rather than conduits of distraction.", category: "Yoga", verseRefs: [550] },
  { id: 59,  tamil: "புண்ணியம்",        transliteration: "puṇṇiyam",         english: "Merit / Virtuous Action",            explanation: "Positive karma accumulated through good actions, devotion, and ethical living. Puṇya creates favourable conditions for spiritual practice. However, the Thirumanthiram consistently points beyond even puṇya to grace (aruḷ) as the ultimate liberating force that no amount of merit can substitute.", category: "Philosophy", verseRefs: [114] },
  { id: 60,  tamil: "ருத்திரன்",        transliteration: "ruttiram",         english: "Rudra / Shiva as Dissolver",         explanation: "A name of Shiva emphasising His dissolving, terrifying aspect. Rudra destroys what is false, impure, or obstructive — His apparent terror is the grace of destruction. In the Thirumanthiram, Rudra is one of Shiva's five roles in the cosmic dance of creation and dissolution.", category: "Deity", verseRefs: [338, 2] },
  { id: 61,  tamil: "சங்கரன்",          transliteration: "sangharan",        english: "Shankara / The Beneficent One",      explanation: "A name of Shiva meaning 'He who bestows auspiciousness.' Shankar is Shiva in His grace-giving aspect — the one who bestows liberation, wisdom, health, and all that is genuinely good upon those who approach Him with devotion and surrender.", category: "Deity", verseRefs: [2, 3] },
  { id: 62,  tamil: "உடல்",             transliteration: "uḍal",             english: "Body / Physical Form",              explanation: "The physical body, which Thirumoolar famously declares to be sacred and necessary for liberation. 'If the body perishes, the life perishes' — the body is not an obstacle to be overcome but the vehicle of liberation itself, to be purified and transformed through yoga until it becomes a fit dwelling for Shiva.", category: "Yoga", verseRefs: [114, 550] },
  { id: 63,  tamil: "உணர்வு",           transliteration: "uṇarvu",           english: "Awareness / Consciousness",         explanation: "Pure awareness — the knowing quality of consciousness that pervades all experience. Thirumoolar's tripartite formula — body (ūṉ), life (uyir), consciousness (uṇarvu) — names the three dimensions of human existence that must all be brought into alignment with Shiva in the practice of yoga.", category: "Philosophy", verseRefs: [550, 2123] },
  { id: 64,  tamil: "உலகம்",            transliteration: "ulagam",           english: "World / This World",               explanation: "The manifest world of experience — not condemned as illusory or evil, but seen as Shiva's creation and the field in which souls learn, grow, and eventually recognise their divine nature. The world is not to be fled from but seen through, until Shiva is recognised as its very substance.", category: "Cosmology", verseRefs: [2, 338] },
  { id: 65,  tamil: "உள்ளம்",           transliteration: "uḷḷam",            english: "Heart / Inner Being",               explanation: "The heart as the seat of consciousness and feeling — not the physical organ but the inner centre of awareness where Shiva resides. The heart-lotus (uḷḷa kamalam) is Shiva's dwelling place within the human body, the place to which all meditation ultimately returns.", category: "Philosophy", verseRefs: [276, 82] },
  { id: 66,  tamil: "உயிர்",            transliteration: "uyir",             english: "Life / Soul / Breath",              explanation: "The living spirit or life-force — used in the Thirumanthiram both for the physical life-breath and for the soul itself. Uyir is the animating principle that makes the body a living being; without uyir, the body (uḍal) is merely inert matter. Preserving and purifying the uyir is the work of yoga.", category: "Soul & Liberation", verseRefs: [114, 550] },
  { id: 67,  tamil: "வழி",              transliteration: "vaḻi",             english: "Path / Way",                        explanation: "The spiritual path — both the outer path of practice and the inner path of recognition. Thirumoolar describes multiple paths to Shiva and consistently points to the innermost path: the turning of attention from outer phenomena to the source of awareness itself, which is Shiva.", category: "Practice", verseRefs: [1420, 550] },
  { id: 68,  tamil: "வேதம்",            transliteration: "vētam",            english: "Veda / Sacred Knowledge",           explanation: "The ancient Sanskrit scriptures of India — the four Vedas (Rig, Yajur, Sama, Atharva). Thirumoolar integrates the Vedic and Agamic traditions, showing they are not contradictory but complementary expressions of the same truth about Shiva. He claims to have heard the Vedas from Shiva Himself.", category: "Scripture", verseRefs: [2, 3] },
  { id: 69,  tamil: "விடுதலை",          transliteration: "viḍuthalai",       english: "Liberation / Freedom / Release",    explanation: "The Tamil word for liberation — both spiritual liberation from the three bonds and the freedom of consciousness recognising its own nature as Shiva. In Thirumoolar's teaching, viḍuthalai is not a distant future goal but a present recognition available to anyone who knows how to look inward.", category: "Soul & Liberation", verseRefs: [2650, 2123] },
  { id: 70,  tamil: "வினை",             transliteration: "vinai",            english: "Karma / Action-residue",             explanation: "The accumulated residue of actions from all past lives that shapes the soul's present and future experience. Vinai is synonymous with karma — the binding force of past deeds. Through yoga, devotion, and grace, accumulated vinai is gradually dissolved until the soul is completely free.", category: "Soul & Liberation", verseRefs: [114, 2123] },
  { id: 71,  tamil: "விண்",             transliteration: "viṇ",              english: "Sky / Heaven / Infinite Space",     explanation: "The sky or celestial space — used both literally and as a symbol for the infinite expanse of pure consciousness. Thirumoolar describes the state of liberation as the mind expanding like the sky — without boundaries, without divisions, luminous and free, containing everything without being contained by anything.", category: "Cosmology", verseRefs: [2650, 2] },
  { id: 72,  tamil: "யோகம்",            transliteration: "yōgam",            english: "Yoga / Union",                      explanation: "The broad path of practices leading to union with Shiva — including ethical conduct, posture, breath, sense-withdrawal, concentration, meditation, and absorption. In the Thirumanthiram, yoga is not merely physical exercise but the complete science of consciousness, expounded in its most comprehensive form in Tantra 3.", category: "Yoga", verseRefs: [550, 551, 1420] },
  { id: 73,  tamil: "யோகி",             transliteration: "yōgi",             english: "Yogi / One Who Practices Yoga",     explanation: "A practitioner of yoga — not merely one who does physical postures but one who has dedicated their entire being to the project of union with Shiva. Thirumoolar himself is the supreme example: thousands of years in samādhi, emerging once each year to transmit a verse of direct spiritual experience.", category: "Yoga", verseRefs: [80, 550, 2123] },

  // ── Deity (additional names and forms) ──────────────────────────────────────
  { id: 74,  tamil: "உமை",                  transliteration: "umai",               english: "Uma / Parvati — Shiva's Consort",           explanation: "The divine consort of Shiva and the embodiment of Shakti in her most intimate form. Uma is simultaneously the cosmic mother, the great Goddess, and the feminine half of ultimate reality. In the Thirumanthiram, Uma is inseparable from Shiva — together they form the complete divine reality. Shiva without Uma is stillness; Uma without Shiva is blind energy.", category: "Deity", verseRefs: [550, 2] },
  { id: 75,  tamil: "கணேசன்",               transliteration: "kaṇēcaṉ",             english: "Ganesha / Remover of Obstacles",             explanation: "The elephant-headed son of Shiva and Parvati, the remover of obstacles, and the lord of beginnings. In the Thirumanthiram, Ganesha appears in the opening Vinayagar Kaapu — all spiritual undertakings are placed under his protection before proceeding. His curved trunk points inward, symbolising the turning of the mind back to its source.", category: "Deity", verseRefs: [1] },
  { id: 76,  tamil: "முருகன்",               transliteration: "murukaṉ",             english: "Murugan / Skanda — Son of Shiva",             explanation: "Son of Shiva and Parvati and the most beloved deity of Tamil Nadu. Murugan represents the highest energy of Shiva's grace — eternally youthful, eternally victorious, wielding the divine lance (Vel) that destroys ignorance. Tamil Shaivism reveres Murugan as the very embodiment of Shiva's loving, accessible nature and the patron deity of Tamil itself.", category: "Deity" },
  { id: 77, tamil: "அர்த்தநாரீசுவரர்",       transliteration: "arttanārīcuvarar",    english: "Ardhanarisvara — Half Shiva Half Shakti",     explanation: "The composite form of Shiva who is half male (Shiva) and half female (Parvati) — one of the most profound images in the tradition. This form declares that ultimate reality transcends gender: consciousness (Shiva) and energy (Shakti) are eternally inseparable. To see one without the other is to see only half of the truth.", category: "Deity", verseRefs: [2] },
  { id: 78, tamil: "அனுக்கிரகம்",            transliteration: "aṉukkirakam",         english: "Anugraha — Liberating Grace",                 explanation: "The fifth of Shiva's five cosmic acts — the grace that directly liberates the soul from the cycle of bondage and rebirth. While the first four acts are cosmic functions operating at a universal scale, anugraha is intensely personal: it is Shiva's individual blessing that lifts each specific soul toward liberation. The entire Thirumanthiram is an extended teaching on how anugraha works and how to receive it.", category: "Deity", verseRefs: [2, 338] },
  { id: 79, tamil: "ஐந்தொழில்",              transliteration: "aintoḻil",            english: "Aintozhil — Five Cosmic Acts of Shiva",       explanation: "Shiva's five inseparable cosmic functions that sustain the entire cycle of existence: Srishti (creation), Sthiti (preservation), Samhara (dissolution), Tirobhava (concealment), and Anugraha (liberation). These five acts are the complete account of how Shiva relates to the universe and to souls. Tantra 2 of the Thirumanthiram is devoted to expounding these five cosmic functions in detail.", category: "Cosmology", verseRefs: [338, 339] },
  { id: 80, tamil: "சிவலிங்கம்",              transliteration: "civaliṅkam",          english: "Shiva Lingam — Supreme Symbol of Shiva",       explanation: "The complete symbol of Shiva — the upright column of pure consciousness (the lingam) arising from the circular base (the yoni, representing Shakti and the manifest world). The Shivalingam is simultaneously the most abstract and the most concrete image of Shiva: infinite, self-luminous consciousness grounded in and expressing through all of existence. Tantra 7 devotes many verses to the different forms of the Lingam.", category: "Deity", verseRefs: [1705, 885] },

  // ── Yoga — specific limbs, channels, chakras ────────────────────────────────
  { id: 81, tamil: "ஆசனம்",                  transliteration: "ācaṉam",              english: "Asana — Yogic Posture",                       explanation: "The third limb of Ashtanga yoga — postures that stabilise the body and purify its channels for meditation. In the Thirumanthiram, asana is not gymnastic exercise but the art of bringing the body into perfect stillness so that energy flows freely through the sushumna. A stable, effortless seat is the necessary foundation on which pranayama, dharana, and samadhi are built.", category: "Yoga", verseRefs: [550] },
  { id: 82, tamil: "நியமம்",                  transliteration: "niyamam",              english: "Niyama — Spiritual Observances",               explanation: "The second limb of Ashtanga yoga — the positive disciplines that cultivate the inner conditions for yoga: cleanliness (shaucha), contentment (santosha), austerity (tapas), self-study (svadhyaya), and surrender to God (Ishvara pranidhana). Where Yama defines what the yogi restrains, Niyama defines what is actively cultivated as daily spiritual discipline.", category: "Yoga", verseRefs: [550] },
  { id: 83, tamil: "தியானம்",                 transliteration: "tiyāṉam",              english: "Dhyana — Meditation",                         explanation: "The seventh limb of Ashtanga yoga — the continuous, uninterrupted flow of attention toward the object of meditation. Dhyana deepens dharana: where dharana is effortful concentration, dhyana is effortless presence. Thirumoolar devotes extensive passages to the forms, objects, and fruits of dhyana, describing it as the portal through which the individual consciousness pours itself into Shiva-consciousness.", category: "Yoga", verseRefs: [550, 2123] },
  { id: 84, tamil: "முத்திரை",                transliteration: "muttirai",             english: "Mudra — Sacred Gesture / Seal",               explanation: "A sacred gesture, posture, or energy-seal that channels and directs the flow of prana in the body. Mudras can involve the hands, eyes, body, or breath. In Shaiva tantra, specific mudras are associated with particular deities, chakras, and states of consciousness — each one a physical encoding of a specific inner reality that, when correctly held, makes that reality accessible.", category: "Yoga", verseRefs: [885, 550] },
  { id: 85, tamil: "நாடி",                    transliteration: "nāṭi",                 english: "Nadi — Subtle Energy Channel",                explanation: "The subtle channels through which prana flows in the yogic body. Classical texts enumerate 72,000 nadis, of which three are paramount: Ida (left/lunar), Pingala (right/solar), and Sushumna (central). The Thirumanthiram describes the nadis as the inner rivers of the subtle body that must be purified and balanced so that Kundalini can rise safely through the central channel to the crown.", category: "Yoga", verseRefs: [550, 885] },
  { id: 86, tamil: "மூலாதாரம்",               transliteration: "mūlātāram",            english: "Muladhara — Root Chakra",                     explanation: "The first of the six chakras, located at the base of the spine — the foundation of the entire subtle body. Muladhara is the seat of dormant Kundalini energy, coiled three and a half times around the central channel. Its four-petalled lotus is associated with the earth element. All upward yogic progress begins with the awakening and purification of this root centre.", category: "Yoga", verseRefs: [550, 885] },

  // ── Philosophy — deeper concepts ─────────────────────────────────────────────
  { id: 87, tamil: "ஞானம்",                   transliteration: "ñāṉam",               english: "Jnana — Direct Knowing",                      explanation: "The path of direct knowledge — not intellectual theology but the living, experiential recognition of Shiva as one's own deepest nature. Jnana is the highest of the four Shaiva paths (Charya, Kriya, Yoga, Jnana). In the Thirumanthiram, Jnana is not separate from love or practice but is their ultimate fruition: the moment the soul recognises that it has always been what it was seeking.", category: "Philosophy", verseRefs: [1420, 2123] },
  { id: 88, tamil: "சரியை",                   transliteration: "cariyai",              english: "Charya — Right Conduct / Service",             explanation: "The first of the four Shaiva paths — the path of right conduct, ethical living, and selfless service in the world and in the temple. Charya is not an inferior path but the necessary foundation: without a life of integrity, compassion, and service, the higher paths of Kriya, Yoga, and Jnana have nothing to grow on. Thirumoolar teaches that every act of service is itself an act of worship.", category: "Practice", verseRefs: [1420] },
  { id: 89, tamil: "ஆனந்தம்",                 transliteration: "āṉantam",              english: "Ananda — Divine Bliss",                       explanation: "The intrinsic bliss of pure consciousness — not pleasure dependent on external conditions but the unconditional joy that is Shiva's own nature and the soul's deepest reality. Ananda is not attained but uncovered: as the soul's bonds dissolve through grace and practice, the ananda that was always present beneath them is simply recognised. It is the third component of the great triad Satchidananda.", category: "Philosophy", verseRefs: [2650, 2123] },
  { id: 90, tamil: "சித்",                    transliteration: "cit",                  english: "Chit — Pure Consciousness",                   explanation: "Pure, self-luminous awareness — the knowing principle that illumines all experience without itself needing illumination. Shiva as Chit is the consciousness that makes all knowing possible. In the Thirumanthiram, recognising this pure consciousness as one's own deepest nature — identical with Shiva — is the essence of Jnana. Chit is what remains when all objects of experience are released.", category: "Philosophy", verseRefs: [2123] },
  { id: 91, tamil: "நித்தியம்",               transliteration: "nittiyam",             english: "Nitya — The Eternal",                         explanation: "That which is eternal, permanent, and unchanging. In the Thirumanthiram, only three realities are truly nitya: Shiva (Pati), the soul (Pasu), and the three bonds (Pasha). Everything else — all of the manifest world — is anitya (transient). Recognising the eternal within the impermanent is a core teaching: the body and the world will pass, but the soul and Shiva never cease.", category: "Philosophy", verseRefs: [114] },
  { id: 92, tamil: "விவேகம்",                  transliteration: "vivēkam",              english: "Viveka — Spiritual Discernment",              explanation: "The capacity to discriminate between the real and the unreal, the eternal and the transient, the self and the not-self. Viveka is the faculty that makes all spiritual life possible: without it, the soul cannot recognise what is worth pursuing or what must be released. In Shaiva yoga, genuine viveka is not a human achievement but a gift of Shiva's grace that dawns when the soul turns inward.", category: "Philosophy", verseRefs: [114] },
  { id: 93, tamil: "வைராக்கியம்",             transliteration: "vairākkiyam",          english: "Vairagya — Dispassion",                       explanation: "The natural dispassion or non-attachment that arises when the soul genuinely recognises the impermanence of worldly things. Vairagya is not forced renunciation through gritted teeth but the natural cooling of desire in the light of clear seeing. In the Thirumanthiram, vairagya and viveka together create the inner freedom in which devotion, yoga, and jnana can grow without obstruction.", category: "Philosophy", verseRefs: [114, 1574] },
  { id: 94, tamil: "அஞ்ஞானம்",                transliteration: "añcñānam",             english: "Ajnana — Ignorance",                          explanation: "Spiritual ignorance — the fundamental not-knowing that causes the soul to mistake the transient for the real and the individual for the absolute. Ajnana is not mere intellectual error but a deep existential confusion rooted in the first bond, āṇava. Shiva's grace dissolves ajnana not by adding information but by removing the veil that was obscuring the ever-present light of Shiva-consciousness.", category: "Philosophy", verseRefs: [2123, 114] },
  { id: 95, tamil: "சாயுச்சியம்",             transliteration: "cāyucciyam",           english: "Sayujya — Union with Shiva",                   explanation: "The fourth and highest stage of liberation — complete union with Shiva in which the soul abides permanently in Shiva-consciousness. In Sayujya, the soul's awareness becomes one with Shiva's awareness — not annihilated but fulfilled beyond measure. The Thirumanthiram's Tantra 9 is devoted to this supreme state, describing it as the soul's eternal home.", category: "Soul & Liberation", verseRefs: [2650, 2123] },

  // ── Practice — specific methods ───────────────────────────────────────────────
  { id: 96, tamil: "ஜபம்",                    transliteration: "japam",                english: "Japa — Mantra Repetition",                    explanation: "The practice of sustained, intentional repetition of a mantra. Japa can be vocal, whispered, or purely mental — the most subtle and most powerful form. The Thirumanthiram teaches that Japa of the Panchakshara (Namasivaya) gradually dissolves the three bonds and replaces the incessant chatter of the mind with the living presence of Shiva. Eventually, the mantra repeats itself — this is Ajapa, the highest form of japa.", category: "Practice", verseRefs: [885, 886] },
  { id: 97, tamil: "பூஜை",                    transliteration: "pūjai",                english: "Puja — Ritual Worship",                       explanation: "The formal ritual worship of Shiva through offerings of flowers, water, light, incense, food, and devotion. Each element of puja corresponds to an inner act: offering flowers is the offering of one's thoughts; offering light is the recognition of Shiva's light within. The Thirumanthiram teaches that external puja is the doorway to inner puja — the ultimate offering is the mind itself.", category: "Practice", verseRefs: [1705] },
  { id: 98, tamil: "திருநீறு",                transliteration: "tiruṉīṟu",             english: "Sacred Ash / Vibhuti",                        explanation: "The sacred white ash worn by Shaiva devotees on the forehead and body. Thiruneeru is produced by burning cow dung in a sacred fire and signifies the burning of karma through the fire of Shiva's grace, the impermanence of the body, and the purity of Shiva-consciousness. Tantra 6 devotes specific verses to the spiritual significance of wearing the sacred ash as an outward sign of inner transformation.", category: "Practice", verseRefs: [1574, 1575] },
  { id: 99, tamil: "ருத்திராட்சம்",            transliteration: "ruttrāṭcam",           english: "Rudraksha — Sacred Beads of Shiva",           explanation: "The berry of the Rudraksha tree, worn as sacred beads by Shaiva devotees and used in japa. The name means 'eye of Rudra (Shiva)' — according to the Thirumanthiram, Shiva's compassionate tears for suffering souls became the Rudraksha seeds. Wearing Rudraksha is believed to purify the aura, protect against negativity, and amplify the power of mantra repetition.", category: "Practice", verseRefs: [1574] },
  { id: 100, tamil: "அபிஷேகம்",                transliteration: "apiṣēkam",             english: "Abhishekam — Sacred Anointing",               explanation: "The ritual bathing of the Shiva Lingam or sacred image with water, milk, curd, honey, coconut water, and sandalwood paste. Each offering substance purifies a specific quality in the devotee who performs it. Abhishekam is one of the most beloved Shaiva rituals — through it the devotee participates directly in the care and adoration of the divine form.", category: "Practice", verseRefs: [1705] },
  { id: 101, tamil: "உபதேசம்",                 transliteration: "upatēcam",             english: "Upadesa — Spiritual Instruction",             explanation: "Direct spiritual instruction transmitted from teacher to student — not mere information transfer but the living transmission of understanding that awakens recognition in the student's own consciousness. The entire Thirumanthiram is upadesa: Thirumoolar is giving direct teaching shaped from his own samādhi experience to awaken the same recognition in those who receive it with devotion and openness.", category: "Practice", verseRefs: [69, 2] },
  { id: 102, tamil: "வணக்கம்",                  transliteration: "vaṇakkam",             english: "Vanakkam — Reverence / Salutation",           explanation: "The gesture of deep reverence — both the external bow and the inner attitude of humility before the divine. Vaṇakkam is not mere social courtesy but a spiritual act: the bowing of the ego before the recognition of something infinitely greater. In the Thirumanthiram, all nine tantras can be understood as one continuous act of vaṇakkam — Thirumoolar placing his entire transmission at the feet of Shiva.", category: "Practice", verseRefs: [2] },
  { id: 103, tamil: "பரிகாரம்",                 transliteration: "parikāram",            english: "Parikara — Ritual Remedy / Grace Act",        explanation: "A remedial ritual or act of worship performed to address specific spiritual obstructions or karmic conditions. In the Thirumanthiram's practical teachings, certain practices serve as parikara — specific methods for dissolving specific types of karmic residue. Grace and parikara work together: the devotee performs the appropriate action; Shiva provides the liberating result.", category: "Practice" },

  // ── Scripture / Tradition ─────────────────────────────────────────────────────
  { id: 104, tamil: "திருமுறை",                transliteration: "tirumurai",             english: "Tirumurai — Sacred Canon of Shaivism",        explanation: "The twelve-volume canon of Tamil Shaiva devotional literature, compiled over many centuries from the hymns of the Nayanmars and other saints. The Thirumanthiram occupies the tenth position as a unique synthesis of devotion and direct yogic transmission. Together, the Tirumurais form the complete scriptural foundation of Tamil Shaivism and are regarded as equivalent in authority to the Sanskrit Vedas for Tamil devotees.", category: "Scripture", verseRefs: [2] },
  { id: 105, tamil: "திருவாசகம்",              transliteration: "tiruvācakam",           english: "Tiruvachakam — Sacred Utterances",             explanation: "The eighth Tirumurai, composed by Manikkavasagar — one of the most beloved devotional texts in Tamil. The title means 'sacred speech.' Manikkavasagar's verses overflow with the anguish and ecstasy of intense devotion. Tamil tradition says that 'the heart that does not melt at Tiruvachakam will not melt at anything.' The Thiruvachakam and Thirumanthiram together form the twin pillars of Tamil Shaiva mysticism.", category: "Scripture" },
  { id: 106, tamil: "சைவ சித்தாந்தம்",        transliteration: "caiva cittāntam",       english: "Shaiva Siddhanta — The Settled Doctrine",      explanation: "The systematic philosophical tradition of Tamil Shaivism — 'the settled, established truth of Shaivism.' Shaiva Siddhanta holds that Pati (God/Shiva), Pasu (souls), and Pasha (bonds) are three distinct eternal realities. It offers the most complete and internally consistent philosophical account of the Shaiva path, and the Thirumanthiram is its primary scriptural source and authority.", category: "Scripture", verseRefs: [2123, 2] },
  { id: 107, tamil: "உண்மை",                   transliteration: "uṇmai",                english: "Unmai — Truth / The Real",                    explanation: "Truth, reality, that which is real and genuine. In the Thirumanthiram, uṇmai points to the lived, experiential truth of Shiva — not doctrine believed on authority but the direct recognition of what is. Thirumoolar consistently distinguishes between conventional appearance (maya-generated) and uṇmai, the underlying reality that yoga and grace progressively reveal.", category: "Philosophy", verseRefs: [2, 2123] },

  // ── Cosmology / Sacred geography ─────────────────────────────────────────────
  { id: 108, tamil: "சிருட்டி",                 transliteration: "ciruṭṭi",              english: "Srishti — Cosmic Creation",                   explanation: "The first of Shiva's five cosmic acts — the continuous bringing-forth of the universe from the divine ground. Creation in the Thirumanthiram is not a one-time event but an ongoing, moment-by-moment arising: the entire universe is continuously being spoken into existence by Shiva. Creation is an act of divine compassion providing the arena for souls to mature through experience toward liberation.", category: "Cosmology", verseRefs: [2, 338] },
  { id: 109, tamil: "திதி",                     transliteration: "titi",                  english: "Sthiti — Cosmic Preservation",                explanation: "The second of Shiva's five cosmic acts — the continuous sustaining and preservation of what has been created. Shiva as preserver maintains the ordered cosmos that allows souls to live, learn, and progress. In Shaiva cosmology, the preserving function is inseparable from grace: the cosmos is sustained specifically so that every soul has the time and space it needs to reach liberation.", category: "Cosmology", verseRefs: [2, 338] },
  { id: 110, tamil: "பஞ்சபூதம்",                transliteration: "pañcapūtam",            english: "Pancha Bhoota — The Five Elements",            explanation: "The five fundamental elements constituting the material universe: earth (maṇ), water (nīr), fire (neruppu), air (kāṟṟu), and space (ākāyam). In the Thirumanthiram's cosmology, these five are not merely physical substances but five modes of Shiva's own being. Correspondingly, the five chakras from Muladhara to Vishuddha are associated with these elements — making yoga the science of mastering the universe through mastering the body.", category: "Cosmology", verseRefs: [2, 338] },
  { id: 111, tamil: "ஏழு உலகங்கள்",             transliteration: "ēḻu ulakaṅkaḷ",        english: "Seven Worlds / Realms of Existence",           explanation: "The seven levels of cosmic existence described in the Thirumanthiram: Bhuloka (earth), Bhuvarloka (atmosphere), Svarloka (heaven), Maharloka, Tapoloka, Satyaloka, and Sivaloka (Shiva's realm). These represent not merely spatial locations but progressive levels of consciousness — and correspond internally to the seven chakras of the yogic body from Muladhara to Sahasrara.", category: "Cosmology", verseRefs: [2] },

  // ── Additional core terms ─────────────────────────────────────────────────────
  { id: 112, tamil: "இறை",                      transliteration: "iṟai",                 english: "Irai — The Divine / God",                     explanation: "The most intimate and universal Tamil word for God or the divine — 'that which pervades and governs.' Iṟai does not carry the weight of theological doctrine but points directly to the experienced, living divine presence that Thirumoolar refers to in everyday speech. It is the word a Tamil speaker reaches for when speaking of God without formality.", category: "Deity", verseRefs: [2] },
  { id: 113, tamil: "பேரின்பம்",                 transliteration: "pēriṉpam",              english: "Perinbam — Supreme Bliss",                    explanation: "The great, transcendent bliss that is Shiva's nature and the soul's deepest longing. Pēriṉpam is the Tamil expression for the supreme happiness that is not derived from any object or circumstance but wells up from the very ground of being. The Thirumanthiram describes this great bliss as the soul's natural state when freed from the three bonds.", category: "Philosophy", verseRefs: [2650, 276] },
  { id: 114, tamil: "தூய்மை",                   transliteration: "tūymai",               english: "Tuymai — Purity / Shuddha",                   explanation: "Purity — both outer and inner. In the Thirumanthiram, purity is not merely ritual cleanliness but the inner radiance that comes from the dissolution of the three bonds. The purified consciousness is like a clean mirror: it reflects Shiva perfectly, without the distortions of ego, desire, and karmic obscuration. All yogic practices are ultimately practices of progressive purification.", category: "Practice", verseRefs: [550] },
  { id: 115, tamil: "மோனம்",                    transliteration: "mōṉam",                english: "Monam — Sacred Silence",                      explanation: "The sacred inner silence that is the natural dwelling-state of the liberated yogi. Monam is not the absence of sound but the silence of the ego — the cessation of the mind's constant self-referential activity. In the Thirumanthiram, those who have 'attained the state of monam' (mōṉē nilai peṟṟār) are the truly realised ones who dwell in Shiva without needing words to describe it.", category: "Philosophy", verseRefs: [2123, 550] },
  { id: 116, tamil: "ஊழ்",                      transliteration: "ūḻ",                   english: "Uzh — Fate / Cosmic Law",                     explanation: "The immutable cosmic law or fate that arises from the accumulated karma of all beings. In the Thirumanthiram, ūḻ represents the bound, predetermined dimension of experience — the groove of past karma. But Shiva's grace is explicitly described as more powerful than ūḻ: divine grace can override karma, lifting the soul beyond its apparent destiny into liberation.", category: "Philosophy", verseRefs: [114] },
  { id: 117, tamil: "சிவபெருமான்",              transliteration: "civapperumāṉ",          english: "Shivaperuman — The Great Lord Shiva",          explanation: "One of the most common full honorific names of Shiva in Tamil — 'the great, supreme Lord Shiva.' The addition of 'perum' (great) and 'mān' (lord) to 'Shiva' creates a name that conveys both immense greatness and personal intimacy. This is the name a Tamil devotee would use with the combination of reverence and familial love that characterises Tamil Shaivism at its deepest.", category: "Deity", verseRefs: [2] },
  { id: 118, tamil: "சாத்திரம்",                transliteration: "cātttiram",             english: "Shastra — Sacred Text / Science",             explanation: "A sacred text or systematised body of knowledge — the textual expression of a complete science of reality. The Thirumanthiram is itself described as a shastra — not a lyric poem alone but a complete shastra on yoga, cosmology, and liberation. In Tamil tradition, a shastra is the written form of what a guru would otherwise transmit orally in direct transmission.", category: "Scripture", verseRefs: [2] },
  { id: 119, tamil: "பேரொளி",                   transliteration: "pēroḷi",               english: "Peroli — The Great Light",                    explanation: "The vast, transcendent light of Shiva-consciousness — a light that has no external source, never dims, and pervades all of reality. In the Thirumanthiram, the inner experience of yoga culminates in the direct perception of this great light at the crown of the head. This light is Shiva Himself — not a vision of something external but the recognition of one's own fundamental nature as radiant awareness.", category: "Deity", verseRefs: [2123, 2] },
  { id: 120, tamil: "பிறவி",               transliteration: "piṟavi",             english: "Piravi — Birth / Cycle of Rebirth",             explanation: "The cycle of birth into embodied existence through karma and the three bonds. Tantra 1 of the Thirumanthiram opens with extended reflection on piravi: birth is not celebrated as a new beginning but recognised as the latest turn in an ancient wheel. The soul takes body after body until, through Shiva's grace, it recognises its own divine nature and the wheel of piravi ceases.", category: "Soul & Liberation", verseRefs: [114, 115] },
  { id: 121, tamil: "மரணம்",               transliteration: "maraṇam",             english: "Marana — Death / The Dissolution of Form",       explanation: "The dissolution of the physical body at the end of each birth. Thirumoolar opens the Thirumanthiram with stark meditations on death — not as morbid fascination but as the great clarifier that reveals what truly matters. The body will perish, youth will fade, all possessions will be lost. Only Shiva and the soul are eternal. Facing marana honestly is the beginning of genuine spiritual life.", category: "Philosophy", verseRefs: [114, 115] },
  { id: 122, tamil: "பிரமன்",              transliteration: "piraman",             english: "Brahma — The Creator",                          explanation: "The cosmic function of creation personified. In Shaiva cosmology, Brahma is not an independent creator but Shiva's instrument — Shiva's creative will expressed as Brahma. The Thirumanthiram consistently subordinates Brahma, Vishnu, and Rudra to Shiva, establishing Shiva as the supreme reality from whom all three derive their powers and functions.", category: "Deity", verseRefs: [338, 339] },
  { id: 123, tamil: "திருமால்",             transliteration: "tirumāl",             english: "Tirumal / Vishnu — The Preserver",               explanation: "The cosmic function of preservation personified — Vishnu (Tirumal, 'the auspicious dark one' in Tamil). In the Thirumanthiram, Vishnu's preserving function is one of Shiva's five cosmic acts carried out through Vishnu. Thirumoolar treats Vishnu with great respect while firmly establishing Shiva as the source of Vishnu's preserving power.", category: "Deity", verseRefs: [338] },
  { id: 124, tamil: "கஞ்சுகம்",             transliteration: "kañcukam",            english: "Kanchuka — The Five Cosmic Coverings",           explanation: "The five 'cloaks' that limit the soul's infinite divine powers into finite human experience: Kala (limiting omnipotence to partial ability), Vidya (limiting omniscience to partial knowledge), Raga (creating specific desires), Niyati (limiting omnipresence to a fixed fate), and Kala (limiting eternity to time-bound experience). Stripping away the kanchukas through yoga and grace progressively restores the soul's original wholeness.", category: "Cosmology", verseRefs: [338] },
  { id: 125, tamil: "புருஷன்",              transliteration: "puruṣan",             english: "Purusha — Pure Witness Consciousness",           explanation: "The pure consciousness principle — the twenty-fifth tattva in Sankhya and the seed of the Shaiva conception of the individual soul. Purusha is pure witnessing awareness that has no qualities, does not act, and is unchanged by anything it witnesses. In the 36 Shaiva tattvas, Purusha corresponds to the soul under the influence of maya — filtered through the five kanchukas into finite, individual experience.", category: "Philosophy", verseRefs: [338] },
  { id: 126, tamil: "பிந்து",               transliteration: "pintu",               english: "Bindu — The Cosmic Point / Seed",                explanation: "The primordial point of concentrated divine consciousness — the seed of all manifestation. Before the universe unfolds, all of existence is compressed into the Bindu: a dimensionless point of infinite potential. In yogic practice, the Bindu is located at the crown of the head — the point where individual consciousness returns to its source. In mantra science, the Bindu is the dot above Om (the anusvara), representing the undifferentiated state from which all sound arises.", category: "Cosmology", verseRefs: [885, 338] },
  { id: 127, tamil: "யோக பந்தம்",           transliteration: "yōka pantam",         english: "Bandha — Yogic Lock / Energy Seal",             explanation: "A physical contraction applied to specific body regions to redirect and concentrate prana in the subtle body. The three primary bandhas are Mula Bandha (root lock), Uddiyana Bandha (abdominal lock), and Jalandhara Bandha (throat lock). When all three are applied simultaneously as Maha Bandha, the entire pranic system is sealed and redirected upward through the Sushumna.", category: "Yoga", verseRefs: [550] },
  { id: 128, tamil: "கேசரி முத்திரை",       transliteration: "kēcari muttirai",     english: "Kechari Mudra — Sky-walking Seal",              explanation: "The 'sky-walking' mudra — folding the tongue back to touch the soft palate or reversing it into the nasal cavity. In the Thirumanthiram, kechari mudra is described as the supreme mudra for immortality: by sealing the palate, the yogi captures divine nectar (amrita) dripping from the crown and prevents its wasteful downward flow. Verse 799 gives extensive treatment of kechari as the key to longevity and liberation.", category: "Yoga", verseRefs: [799, 800] },
  { id: 129, tamil: "பத்மாசனம்",            transliteration: "patmācaṉam",          english: "Padmasana — Lotus Posture",                     explanation: "The lotus posture — each foot resting on the opposite thigh, forming a stable, symmetrical base. Padmasana is one of the three asanas given prominence in the Thirumanthiram. Its symmetry balances the solar and lunar energy channels; its stability allows the spine to be perfectly upright without effort; and its closed-circuit form keeps prana contained within the body during meditation.", category: "Yoga", verseRefs: [558] },
  { id: 130, tamil: "பூரகம்",               transliteration: "pūrakam",             english: "Puraka — Inhalation",                           explanation: "The inhalation phase of pranayama — the drawing in of breath with full awareness. In the Thirumanthiram's detailed pranayama teachings, puraka fills the body with prana and is associated with the solar channel. The ratio of puraka to kumbhaka (retention) to rechaka (exhalation) forms the precise technical foundation of all pranayama practice.", category: "Yoga", verseRefs: [550, 551] },
  { id: 131, tamil: "ரேசகம்",               transliteration: "rēcakam",             english: "Rechaka — Exhalation",                          explanation: "The exhalation phase of pranayama — the complete, conscious release of breath. Rechaka removes stale prana and is associated with the lunar channel. Complete exhalation is essential for full inhalation. In the metaphor of Shaiva yoga, rechaka represents the letting go of all that is not Shiva.", category: "Yoga", verseRefs: [550, 551] },
  { id: 132, tamil: "மாத்திரை",             transliteration: "māttiraii",           english: "Matra — Unit of Time in Pranayama",             explanation: "The standard unit of time used to measure the duration of each phase of pranayama — approximately the time of a single snap of fingers. Verse 568 of the Thirumanthiram gives specific matra ratios for each phase. Classical practice prescribes a 1:4:2 ratio of puraka:kumbhaka:rechaka.", category: "Yoga", verseRefs: [568] },
  { id: 133, tamil: "வாசி",                 transliteration: "vāci",                english: "Vasi — The Vital Breath as Spiritual Force",     explanation: "In Tamil yogic tradition, vasi is the life-force (prana) as specifically experienced in breath control — the 'inner wind' the yogi learns to master. In the Thirumanthiram, controlling vasi controls the mind: 'where the breath goes, the mind follows.' The entire pranayama system is sometimes called 'vaasi yoga' in Tamil tradition.", category: "Yoga", verseRefs: [550, 790] },
  { id: 134, tamil: "அகிம்சை",             transliteration: "akimcai",             english: "Ahimsa — Non-violence / Non-harming",            explanation: "The first and most fundamental of the five yamas — the commitment to non-harm in thought, word, and action toward all beings. The Thirumanthiram is unambiguous: without ahimsa there is no yoga. All higher practices rest on this foundation. The yogi who harms others cannot find the inner stillness required for meditation.", category: "Yoga", verseRefs: [550] },
  { id: 135, tamil: "சத்தியம்",             transliteration: "cattiyam",            english: "Satya — Truthfulness",                          explanation: "The second yama — speaking and living in truth. In the Thirumanthiram, satya is not merely avoiding lies but aligning speech, thought, and action with Shiva's own nature as truth (uṇmai). When the yogi's speech is completely purified, their words carry the power of Shiva — whatever they speak comes to be.", category: "Yoga", verseRefs: [550] },
  { id: 136, tamil: "பிரமசரியம்",           transliteration: "piramaccariyam",      english: "Brahmacharya — Celibacy / Walking in the Absolute", explanation: "The fourth yama — the discipline of sexual continence, literally 'walking in Brahman.' The Thirumanthiram gives extensive teachings on brahmacharya: vital energy (ojas) that would otherwise be expended sexually is transmuted through yoga into the spiritual energy (tejas) that fires pranayama and meditation.", category: "Yoga", verseRefs: [550] },
  { id: 137, tamil: "சந்தோஷம்",             transliteration: "cantōṣam",            english: "Santosha — Contentment",                        explanation: "The second niyama — the cultivation of genuine contentment with what is, independent of external circumstances. Santosha is not resignation but the recognition that Shiva is fully present in the current moment regardless of outward conditions. The yogi who has santosha is unshakeable.", category: "Yoga", verseRefs: [550] },
  { id: 138, tamil: "அமுதம்",               transliteration: "amutam",              english: "Amrita / Amutam — The Divine Nectar",            explanation: "The nectar of immortality — the divine fluid said to drip from the bindu at the crown centre during advanced yoga. In the Thirumanthiram, amrita is a physiological reality of the subtle body. Kechari mudra and specific inversions are taught as means of capturing this nectar before it is consumed by the digestive fire below the navel.", category: "Yoga", verseRefs: [799, 800, 885] },
  { id: 139, tamil: "வர்ண மாலை",            transliteration: "varṇa mālai",         english: "Varna Mala — Garland of Letters / Nadi Mantra",  explanation: "The 'garland of letters' — the 729 nadis that the Thirumanthiram associates with the complete system of Sanskrit sounds. Verse 702 expounds the Varna Mala as a map of the subtle body: each letter of the Sanskrit alphabet corresponds to a specific nadi and dimension of the body's pranic system.", category: "Yoga", verseRefs: [702] },
  { id: 140, tamil: "தேக சித்தி",           transliteration: "tēka citti",          english: "Deha Siddhi — Perfection / Immortality of the Body", explanation: "The yogic attainment of a perfected, immortal body (kaya kalpa) — the physical body transformed through sustained yoga, pranayama, and the capture of inner nectar. The Tamil Siddhar tradition uniquely places special emphasis on the transformation of the physical body as a vehicle of liberation. Thirumoolar famously declared: 'I venerated the body, and the body became the temple of the Lord.'", category: "Yoga", verseRefs: [114, 1705] },
  { id: 141, tamil: "பக்தி",                transliteration: "pakti",               english: "Bhakti — Loving Devotion to Shiva",             explanation: "Wholehearted, loving devotion to Shiva — the feeling-path of the heart. Bhakti in the Thirumanthiram is not separate from yoga and jnana but is their flowering: when yoga purifies the heart and jnana reveals Shiva as one's own nature, what remains is an unceasing flow of loving recognition.", category: "Practice", verseRefs: [1420, 1574, 82] },
  { id: 142, tamil: "பாதம்",                transliteration: "pātam",               english: "Pada — Path / Stage of the Shaiva Way",          explanation: "The four stages of the Shaiva path: Charya (right conduct), Kriya (ritual action), Yoga (inner practice), and Jnana (direct knowledge). These four padas are not sequential stages but four simultaneous dimensions of the complete life. Tantra 5 of the Thirumanthiram expounds how these four padas integrate into a single living path toward Shiva.", category: "Practice", verseRefs: [1420] },
  { id: 143, tamil: "மலம்",                 transliteration: "malam",               english: "Mala — Spiritual Impurity / Fetter",            explanation: "The three fundamental impurities (malas) obscuring the soul's divine nature: Anava mala (primal egoism), Karma mala (residue of past actions), and Maya mala (identification with matter). These deep structural conditions require Shiva's direct grace to dissolve. The entire path of the Thirumanthiram is the process by which these three malas are progressively purified and ultimately removed.", category: "Soul & Liberation", verseRefs: [2123, 338] },
  { id: 144, tamil: "வேதாந்தம்",            transliteration: "vētāntam",            english: "Vedanta — State Beyond Scripture",              explanation: "In verse 225, Thirumoolar uses 'Vedanta' in its literal sense: 'veda-anta' — the end and transcendence of scriptural knowledge. True Vedanta is a living state: the soul has moved past all concepts into direct Shiva-recognition. Scriptural knowledge serves only to point the way — Vedanta is the state after the finger is no longer needed.", category: "Philosophy", verseRefs: [225] },
  { id: 145, tamil: "அணிமா",                transliteration: "aṇimā",               english: "Anima — Power of Infinitesimal Smallness",       explanation: "The first of the eight great siddhis — the power to make the body infinitesimally small. Anima is not merely a magical feat but a demonstration of mastery over matter: having realised that the body is a temporary pattern in Shiva's consciousness, the master reshapes that pattern at will. Tantra 7 presents anima as a natural by-product of complete Shiva-realisation.", category: "Yoga", verseRefs: [1705, 1706] },
  { id: 146, tamil: "லகிமா",                transliteration: "lakimā",              english: "Laghima — Power of Infinite Lightness / Levitation", explanation: "The fourth siddhi — the power to make the body as light as air, enabling levitation. Laghima represents mastery of the air element and the dissolution of matter's gravitational pull. In the inner sense, laghima is the lightness of a consciousness freed from the burden of karma and ego.", category: "Yoga", verseRefs: [1705, 1706] },
  { id: 147, tamil: "சொப்பனம்",             transliteration: "coppannam",           english: "Svapna — The Dream State",                      explanation: "The dreaming state — the second of the three familiar states, in which the body rests but the mind creates an inner world from karmic residues. 'Svapna-in-jagrat' is the state of one who, while outwardly awake, is inwardly absorbed in the thought-world without awareness — the condition of ordinary unexamined life.", category: "Philosophy", verseRefs: [2202, 2123] },
  { id: 148, tamil: "சுழுத்தி",             transliteration: "cuḻutti",             english: "Sushupti — Deep Dreamless Sleep",                explanation: "The state of deep dreamless sleep — the third familiar state, in which neither body nor mind is active and consciousness returns to its seed state. In sushupti, the soul approaches its own true nature most closely among the three ordinary states, yet without awareness of it.", category: "Philosophy", verseRefs: [2202, 2123] },
  { id: 149, tamil: "கேவலம்",               transliteration: "kēvalam",              english: "Kevala — Shiva's Absolute Aloneness / Pure State", explanation: "Shiva's state of absolute aloneness prior to creation — pure, undifferentiated consciousness before the arising of any dual relationship. Kevala also describes the soul that has been completely purified and stripped of all bonds. The Thirumanthiram's descriptions of the fully liberated state (Sayujya) approach this kevalā: the soul and Shiva in the fullness of their essential nature.", category: "Soul & Liberation", verseRefs: [2650, 2123] },

];

export function searchDictionary(query: string): DictionaryTerm[] {
  const q = query.toLowerCase().trim();
  if (!q) return DICTIONARY_TERMS;
  return DICTIONARY_TERMS.filter(
    (t) =>
      t.tamil.includes(q) ||
      t.transliteration.toLowerCase().includes(q) ||
      t.english.toLowerCase().includes(q) ||
      t.explanation.toLowerCase().includes(q),
  );
}
